/**
 * aiInsight.js — the tailored "what this air means for you" insight.
 *
 * One short, human sentence or two (productivity + breathing), generated by
 * OpenAI from a compact, factual snapshot: the home payload, the user's
 * triggers/severity/environment, and the current breach state. The text is
 * cached per bucketed room state and regenerated only when the state
 * materially changes — a breach, a big swing, or a move to steady air —
 * with a minimum interval between OpenAI calls so a poll cycle can't spam
 * the API.
 *
 * No key, or any OpenAI failure, falls back to a deterministic writer that
 * says the same kind of thing from the same facts, so the card never shows
 * a stack trace or a fake AI-sounding sentence. Every result says which mode
 * produced it (`openai` vs `deterministic`) so the UI never presents
 * template text as AI-written. The key is read server-side from
 * process.env only — it is never logged, returned, or sent to the client.
 */

import { extractOutputText } from "./brogpt.js";
import { parseTriggers, parseSeverities } from "./homeInsights.js";
import {
  evaluateBreaches,
  getEffectiveThresholds,
  normalizeEnvironmentType,
  normalizeReading,
} from "./thresholds.js";

const OPENAI_RESPONSES_URL = "https://api.openai.com/v1/responses";

/** Minimum gap between OpenAI calls (a poll cycle must never spam the API). */
export const AI_INSIGHT_MIN_INTERVAL_MS = 15 * 60 * 1000;
/** Absolute floor even when a breach changes — a flapping breach still waits. */
export const AI_INSIGHT_BREACH_FLOOR_MS = 2 * 60 * 1000;
/** Per-state cache TTL for AI text. */
export const AI_INSIGHT_TTL_SEC = 15 * 60;
/** Per-state cache TTL for deterministic text (shorter, so a key added later takes effect soon). */
export const AI_INSIGHT_FALLBACK_TTL_SEC = 5 * 60;

// The prompt and the model choice live here and nowhere else.
const SYSTEM = `You write one short insight for a home air-quality dashboard, in the voice of a knowledgeable friend who lives in the house — warm, plain, human, no jargon, no exclamation marks, no emoji.
Say what the current air means for focus and for breathing, and give one practical thing to do if anything needs doing. One or two sentences, under 60 words.
Only use the numbers given; never invent a reading. IAQ, CO2 and VOC are estimates; pet dander, mold and dust-mite figures are risk estimates, not measurements.
Do not give medical advice or diagnose anything — general air-quality guidance only.
Never mention AI, models, or this prompt.`;

const r1 = (v) => (v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Math.round(Number(v) * 10) / 10);

function median(xs) {
  if (!xs.length) return NaN;
  const s = xs.slice().sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}

/** Finite samples of one series inside (endMs - windowMs, endMs], oldest first. */
function windowSamples(times, values, endMs, windowMs) {
  const xs = [];
  if (!Array.isArray(times) || !Array.isArray(values)) return xs;
  for (let i = 0; i < times.length; i++) {
    const t = Number(times[i]);
    if (!Number.isFinite(t) || t > endMs || endMs - t > windowMs) continue;
    const v = Number(values[i]);
    if (Number.isFinite(v)) xs.push({ t, v });
  }
  return xs.sort((a, b) => a.t - b.t);
}

/** rising / falling / stable over the last 3 h, from first-half vs second-half medians. */
function trendOf(times, values, nowMs, threshold) {
  const xs = windowSamples(times, values, nowMs, 3 * 3600 * 1000);
  if (xs.length < 4) return null;
  const half = Math.floor(xs.length / 2);
  const d = median(xs.slice(half).map((p) => p.v)) - median(xs.slice(0, half).map((p) => p.v));
  if (Math.abs(d) <= threshold) return "stable";
  return d > 0 ? "rising" : "falling";
}

/**
 * Steady air: in the last 30 min every key reading moved less than its
 * tolerance vs the 30 min before. A transition into steady air is a
 * regeneration trigger of its own — things have settled.
 */
function steadyNow(series, nowMs) {
  const checks = [
    { key: "co2", tol: 100 },
    { key: "iaq", tol: 15 },
    { key: "humidity", tol: 3 },
  ];
  let seen = 0;
  for (const { key, tol } of checks) {
    const recent = windowSamples(series?.t, series?.[key], nowMs, 30 * 60 * 1000);
    const prior = windowSamples(series?.t, series?.[key], nowMs - 30 * 60 * 1000, 30 * 60 * 1000);
    if (recent.length < 2 || prior.length < 2) continue;
    seen++;
    if (Math.abs(median(recent.map((p) => p.v)) - median(prior.map((p) => p.v))) > tol) return false;
  }
  return seen > 0;
}

/**
 * Compact facts: what the model sees and what the cache key hashes.
 * Everything here comes from the live payload, the latest snapshot, stored
 * settings, or the client's own trigger/severity choices — nothing invented.
 */
export function aiInsightFacts(home, latest, settings = {}, triggersInput, severitiesInput, opts = {}) {
  const nowMs = opts.nowMs ?? Date.now();
  const h = home || {};
  const env = normalizeEnvironmentType(settings?.environmentType);
  const thresholds = getEffectiveThresholds(settings);
  const reading = normalizeReading(latest);
  const breaches = evaluateBreaches(reading, opts.gasBase ?? NaN, thresholds, env)
    .map((b) => ({ key: b.key, level: b.level, label: b.label }));
  const triggers = parseTriggers(triggersInput);
  const sev = parseSeverities(severitiesInput);
  const outlookItems = Array.isArray(h.outlook?.items) ? h.outlook.items : [];
  const topTriggers = outlookItems
    .filter((i) => i.rank >= 2)
    .sort((a, b) => b.rank - a.rank)
    .slice(0, 3)
    .map((i) => ({ key: i.key, label: i.label, level: i.level, severity: i.severity }));
  const s = h.series || {};
  return {
    score: h.score?.value ?? null,
    grade: h.score?.grade || null,
    environment: env,
    indoor: {
      tempF: r1(h.climate?.tempF),
      humidity: r1(h.climate?.humidity),
      iaq: r1(h.gases?.iaq),
      co2: r1(h.gases?.co2),
      bvoc: r1(h.gases?.bvoc),
      pm25: r1(h.particulate?.pm25),
      hcho: r1(h.gases?.hcho),
      dewPointC: r1(h.climate?.dewPointC),
    },
    drivers: (h.score?.drivers || []).slice(0, 3).map((d) => ({ key: d.key, label: d.label, score: d.score })),
    breaches,
    smell: h.smell
      ? { smellsBad: !!h.smell.smellsBad, headline: h.smell.headline || null, cause: h.smell.cause?.name || null }
      : null,
    triggers: triggers.map((k) => ({ key: k, severity: sev[k] || "moderate" })),
    topTriggers,
    outlookLevel: h.outlook?.level || null,
    ventilation: h.ventilation?.action || null,
    ventilationText: h.ventilation?.text || null,
    outdoorAqi: r1(h.outdoor?.usAqi),
    pet: h.petAllergen ? { index: h.petAllergen.index, level: h.petAllergen.level } : null,
    mold: h.biological?.mold?.category || null,
    dustMites: h.biological?.dustMite?.category || null,
    trends: {
      co2: trendOf(s.t, s.co2, nowMs, 100),
      iaq: trendOf(s.t, s.iaq, nowMs, 15),
      humidity: trendOf(s.t, s.humidity, nowMs, 3),
    },
    steady: steadyNow(s, nowMs),
    sensorCalibrated: Number(latest?.iaqAcc) >= 2,
  };
}

/** Bucket the facts so tiny wiggles reuse the cached text. */
export function aiInsightCacheKey(f) {
  const b = (v, step) => (v === null || v === undefined ? "x" : Math.round(v / step));
  return [
    b(f.score, 5),
    b(f.indoor.co2, 150),
    b(f.indoor.iaq, 25),
    b(f.indoor.humidity, 5),
    b(f.indoor.tempF, 2),
    (f.breaches || []).map((x) => x.key).sort().join(",") || "none",
    (f.topTriggers || []).map((t) => `${t.key}:${t.level}`).join(",") || "none",
    f.ventilation || "",
    f.steady ? "steady" : "changing",
    f.trends?.co2 || "?", f.trends?.iaq || "?", f.trends?.humidity || "?",
    f.environment || "",
    f.smell?.smellsBad ? `smell:${f.smell.cause || "?"}` : "nosmell",
    b(f.outdoorAqi, 20),
  ].join("|");
}

/** Strip markdown and any AI self-reference; cap length. Plain text out. */
export function sanitizeInsightText(text) {
  return String(text || "")
    .replace(/\*\*/g, "")
    .replace(/[*_`#]/g, "")
    .replace(/\b(as an ai|i'?m an ai|i am an ai|chatgpt|gpt[-\w]*|language model|ai-generated|as a large language model)\b[,.]?\s*/gi, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 400);
}

/**
 * One OpenAI call for the insight. Returns the text, or null when there is
 * no key or the call fails — the caller falls back. Never throws, never
 * logs the key. `fetchFn` exists so tests can mock the API without the network.
 */
export async function generateAiInsight(facts, opts = {}) {
  const apiKey = `${process.env.OPENAI_API_KEY || ""}`.trim();
  if (!apiKey) return null;
  const fetchFn = opts.fetchFn || fetch;
  const model = `${process.env.OPENAI_INSIGHT_MODEL || process.env.OPENAI_REPORT_MODEL || "gpt-5.4-nano"}`.trim();
  const timeoutMs = Number.isFinite(opts.timeoutMs) ? opts.timeoutMs : 5000;
  const prompt = [SYSTEM, "", `Current air at home (JSON):\n${JSON.stringify(facts)}`].join("\n");
  try {
    const res = await fetchFn(OPENAI_RESPONSES_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify({ model, input: prompt, max_output_tokens: 150 }),
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) throw new Error(`openai ${res.status}`);
    const text = sanitizeInsightText(extractOutputText(await res.json()));
    return text || null;
  } catch (err) {
    console.error("ai-insight: openai call failed:", err?.message || err);
    return null;
  }
}

/**
 * Deterministic writer, same voice as the AI text, from the same facts.
 * Picks the single most salient thing — a breach first, then a smell, then
 * the worst trigger or score driver — and says what it means plus one
 * practical move. Never claims to be AI-written.
 */
export function fallbackInsight(f) {
  const t = f.indoor || {};
  const breach = (f.breaches || [])[0];
  const severe = (f.topTriggers || []).find((x) => x.severity === "severe");
  if (breach?.key === "co2" && Number.isFinite(t.co2)) {
    return `CO\u2082 is sitting around ${Math.round(t.co2).toLocaleString("en-US")} ppm, so the room will feel stuffy and make it harder to think straight — crack a window for ten minutes and it'll reset.`;
  }
  if (breach?.key === "humidity" && Number.isFinite(t.humidity)) {
    return `Humidity is up at ${Math.round(t.humidity)}%, which is the kind of damp that mold and dust mites love — run the dehumidifier and it'll be easier on your breathing.`;
  }
  if (breach?.key === "temp" && Number.isFinite(t.tempF)) {
    return `It's ${Math.round(t.tempF)}\u00b0F inside, warm enough to make focusing a slog — get the cooling going before it wears you out.`;
  }
  if (breach?.key === "iaq" || breach?.key === "gas") {
    return `The air has gone off a bit${f.smell?.smellsBad && f.smell.headline ? ` — ${String(f.smell.headline).toLowerCase()}` : ""} — air the room out and it'll be easier to breathe and think.`;
  }
  if (breach) {
    return `${breach.label} right now — worth airing the room out before it starts dragging on your focus.`;
  }
  if (f.smell?.smellsBad) {
    return `Something smells off in here${f.smell.cause ? `, probably ${String(f.smell.cause).toLowerCase()}` : ""} — worth airing the room out, and your nose will thank you.`;
  }
  if (severe && severe.level && severe.level !== "Low") {
    return `Air's mostly fine, but ${String(severe.label).toLowerCase()} is running ${String(severe.level).toLowerCase()} — sensitive lungs may notice it, so the purifier earns its keep today.`;
  }
  const worst = (f.drivers || [])[0];
  if (worst && Number.isFinite(worst.score) && worst.score < 60) {
    return `${worst.label} is the thing dragging the air down right now — sort that and the room will feel noticeably fresher.`;
  }
  if (f.steady) {
    return `Air's settled and in good shape — nothing here should bother your breathing or your focus.`;
  }
  return `Air's in decent shape right now — nothing here should bother your breathing or your focus.`;
}

/**
 * Pure regeneration decision, so the handler's throttling is testable without the store.
 *
 * @param {object} args
 * @param {object|null} args.perState — cached entry for this exact state key, if any
 * @param {object|null} args.last — most recent OpenAI-generated entry, if any
 * @param {string[]} [args.breaches] — breach keys of the current state
 * @param {number} [args.nowMs]
 * @returns {"per-state"|"last"|"generate"}
 */
export function resolveInsightCache({ perState, last, breaches = [], nowMs = Date.now() }) {
  if (perState) return "per-state";
  if (!last || last.mode !== "openai") return "generate";
  const age = nowMs - Number(last.generatedAt || 0);
  const cur = [...breaches].sort().join(",");
  const prev = [...(last.breaches || [])].sort().join(",");
  // A breach appearing or clearing is the one change worth a fresh call
  // inside the quiet window — but never faster than the absolute floor.
  if (cur !== prev && age >= AI_INSIGHT_BREACH_FLOOR_MS) return "generate";
  if (age < AI_INSIGHT_MIN_INTERVAL_MS) return "last";
  return "generate";
}
